        ("carrier","sun_gear"),("sun_gear","planet_bushing_1"),("sun_gear","planet_bushing_2"),("sun_gear","planet_bushing_3"),("sun_gear","planet_pin_1"),("sun_gear","planet_pin_2"),("sun_gear","planet_pin_3"),("sun_gear","carrier_bearing"),("sun_gear","output_indicator"),("sun_gear","input_crank"),("sun_gear","center_pedestal"),("sun_gear","crank_handle"),("sun_gear","input_bearing"),("sun_gear","base"),
