        ("planet_gear_2","carrier_bearing"),("planet_gear_2","input_crank"),("planet_gear_2","center_pedestal"),("planet_gear_2","output_indicator"),("planet_gear_2","ring_post_2"),("planet_gear_2","planet_gear_3"),("planet_gear_2","input_bearing"),("planet_gear_2","planet_bushing_1"),("planet_gear_2","base"),("planet_gear_2","planet_pin_1"),
        ("planet_gear_3","carrier_bearing"),("planet_gear_3","input_crank"),("planet_gear_3","center_pedestal"),("planet_gear_3","output_indicator"),("planet_gear_3","ring_post_3"),("planet_gear_3","input_bearing"),("planet_gear_3","planet_bushing_1"),("planet_gear_3","base"),("planet_gear_3","planet_pin_1"),
